import React, { useState, useEffect } from "react";
import { db } from "../../firebaseConfig";
import { collection, query, where, getDocs } from "firebase/firestore";
import './ExamPage.css';

const ExamPage = ({ studentClass, studentSubject }) => {
  const [exams, setExams] = useState([]);

  useEffect(() => {
    const fetchExams = async () => {
      try {
        const q = query(
          collection(db, "exams"),
          where("classLevel", "==", studentClass),
          where("subject", "==", studentSubject)
        );
        const querySnapshot = await getDocs(q);
        const fetchedExams = querySnapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        }));
        setExams(fetchedExams);
      } catch (error) {
        console.error("Error fetching exams:", error);
      }
    };

    fetchExams();
  }, [studentClass, studentSubject]);

  return (
    <div className="exam-page">
      <h2>Available Exams</h2>
      {exams.length > 0 ? (
        exams.map((exam) => (
          <div key={exam.id} className="exam-card">
            <h3>{exam.examTitle}</h3>
            <p>Subject: {exam.subject}</p>
            <p>Class: {exam.classLevel}</p>
          </div>
        ))
      ) : (
        <p>No exams available for your class and subject.</p>
      )}
    </div>
  );
};

export default ExamPage;
